/**
 * ============================================================================
 *  Secure Authentication & Rate Limiting Handler
 * ============================================================================
 *
 *  A production-ready, dependency-free (Node.js `crypto` only) module that
 *  provides:
 *
 *   - Password hashing & verification using scrypt with per-user random salt,
 *     versioned/encoded hash strings and constant-time comparison.
 *   - HMAC-SHA256 signed, JSON-serialized stateless access tokens (JWT-like)
 *     with issuer/audience/expiry/not-before validation and clock skew support.
 *   - Opaque, hashed-at-rest refresh tokens with rotation + reuse detection
 *     (token family revocation on replay).
 *   - Sliding-window and token-bucket rate limiting with a pluggable store.
 *   - Progressive brute-force protection: per-identifier and per-IP counters,
 *     exponential backoff lockouts, and generic error responses to avoid user
 *     enumeration.
 *   - TOTP (RFC 6238) two-factor authentication with drift window + replay
 *     protection, plus single-use recovery codes.
 *   - CSRF double-submit token issuing/verification.
 *   - Structured security audit events via an injectable sink.
 *
 *  Everything is implemented in-file with an in-memory default store; swap in
 *  Redis/Postgres by implementing the `AuthStore` / `RateLimitStore` interfaces.
 * ============================================================================
 */

import {
  createHmac,
  randomBytes,
  randomUUID,
  scrypt as _scrypt,
  timingSafeEqual,
} from 'crypto';

/* ==========================================================================
 * Utilities: encoding, time, constant-time comparison
 * ========================================================================== */

/** Promise wrapper around Node's scrypt. */
function scryptAsync(
  password: Buffer,
  salt: Buffer,
  keylen: number,
  options: { N: number; r: number; p: number; maxmem: number },
): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    _scrypt(password, salt, keylen, options, (err, derived) => {
      if (err) reject(err);
      else resolve(derived as Buffer);
    });
  });
}

/** Base64url encode without padding. */
export function base64UrlEncode(input: Buffer | string): string {
  const buf = typeof input === 'string' ? Buffer.from(input, 'utf8') : input;
  return buf
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/g, '');
}

/** Base64url decode (tolerates missing padding). Throws on invalid chars. */
export function base64UrlDecode(input: string): Buffer {
  if (!/^[A-Za-z0-9_-]*$/.test(input)) {
    throw new Error('Invalid base64url input');
  }
  const pad = input.length % 4 === 0 ? '' : '='.repeat(4 - (input.length % 4));
  return Buffer.from(input.replace(/-/g, '+').replace(/_/g, '/') + pad, 'base64');
}

/** Constant-time string comparison that does not leak length via early exit. */
export function safeEqual(a: string, b: string): boolean {
  const ab = Buffer.from(a, 'utf8');
  const bb = Buffer.from(b, 'utf8');
  // Hash both to fixed length so length differences don't short-circuit.
  const ah = createHmac('sha256', 'ct-compare').update(ab).digest();
  const bh = createHmac('sha256', 'ct-compare').update(bb).digest();
  return timingSafeEqual(ah, bh) && ab.length === bb.length;
}

/** Constant-time buffer comparison. */
export function safeEqualBuffer(a: Buffer, b: Buffer): boolean {
  if (a.length !== b.length) {
    // Still perform a comparison of equal-length digests to normalize timing.
    const ah = createHmac('sha256', 'ct-compare').update(a).digest();
    const bh = createHmac('sha256', 'ct-compare').update(b).digest();
    timingSafeEqual(ah, bh);
    return false;
  }
  return timingSafeEqual(a, b);
}

/** Cryptographically strong URL-safe random token. */
export function generateSecureToken(byteLength = 32): string {
  if (!Number.isInteger(byteLength) || byteLength < 16 || byteLength > 1024) {
    throw new RangeError('byteLength must be an integer between 16 and 1024');
  }
  return base64UrlEncode(randomBytes(byteLength));
}

/** SHA-256 HMAC digest helper. */
function hmacSha256(key: Buffer | string, data: Buffer | string): Buffer {
  return createHmac('sha256', key).update(data).digest();
}

/** Monotonic-ish clock abstraction (injectable for tests). */
export interface Clock {
  now(): number; // epoch milliseconds
}

export const systemClock: Clock = { now: () => Date.now() };

/** Sleep helper used for constant-ish response times. */
function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, Math.max(0, ms)));
}

/* ==========================================================================
 * Error taxonomy
 * ========================================================================== */

export type AuthErrorCode =
  | 'INVALID_CREDENTIALS'
  | 'ACCOUNT_LOCKED'
  | 'ACCOUNT_DISABLED'
  | 'RATE_LIMITED'
  | 'MFA_REQUIRED'
  | 'MFA_INVALID'
  | 'TOKEN_EXPIRED'
  | 'TOKEN_INVALID'
  | 'TOKEN_REVOKED'
  | 'TOKEN_REUSED'
  | 'CSRF_INVALID'
  | 'WEAK_PASSWORD'
  | 'USER_EXISTS'
  | 'NOT_FOUND'
  | 'VALIDATION_ERROR'
  | 'INTERNAL_ERROR';

export class AuthError extends Error {
  public readonly code: AuthErrorCode;
  public readonly httpStatus: number;
  public readonly retryAfterSeconds?: number;
  public readonly details?: Record<string, unknown>;

  constructor(
    code: AuthErrorCode,
    message: string,
    httpStatus = 400,
    options?: { retryAfterSeconds?: number; details?: Record<string, unknown> },
  ) {
    super(message);
    this.name = 'AuthError';
    this.code = code;
    this.httpStatus = httpStatus;
    this.retryAfterSeconds = options?.retryAfterSeconds;
    this.details = options?.details;
    Object.setPrototypeOf(this, AuthError.prototype);
  }

  toJSON(): Record<string, unknown> {
    return {
      error: this.code,
      message: this.message,
      ...(this.retryAfterSeconds !== undefined
        ? { retryAfterSeconds: this.retryAfterSeconds }
        : {}),
      ...(this.details ? { details: this.details } : {}),
    };
  }
}

/* ==========================================================================
 * Password policy & hashing
 * ========================================================================== */

export interface PasswordPolicy {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireDigit: boolean;
  requireSymbol: boolean;
  /** Reject passwords containing these substrings (case-insensitive). */
  blocklist: string[];
  /** Reject passwords containing the username/email local-part. */
  rejectUserInfo: boolean;
}

export const DEFAULT_PASSWORD_POLICY: PasswordPolicy = {
  minLength: 12,
  maxLength: 256,
  requireUppercase: true,
  requireLowercase: true,
  requireDigit: true,
  requireSymbol: true,
  blocklist: [
    'password',
    'passwort',
    '123456',
    'qwerty',
    'letmein',
    'welcome',
    'admin',
    'iloveyou',
    'monkey',
    'dragon',
    'football',
    'abc123',
  ],
  rejectUserInfo: true,
};

export interface PasswordValidationResult {
  valid: boolean;
  errors: string[];
  /** 0..4 heuristic strength score. */
  score: number;
}

export function validatePasswordStrength(
  password: string,
  policy: PasswordPolicy = DEFAULT_PASSWORD_POLICY,
  userInfo: string[] = [],
): PasswordValidationResult {
  const errors: string[] = [];
  if (typeof password !== 'string') {
    return { valid: false, errors: ['Password must be a string'], score: 0 };
  }
  const normalized = password.normalize('NFKC');

  if (normalized.length < policy.minLength) {
    errors.push(`Password must be at least ${policy.minLength} characters long`);
  }
  if (normalized.length > policy.maxLength) {
    errors.push(`Password must be at most ${policy.maxLength} characters long`);
  }
  if (policy.requireUppercase && !/[A-Z]/.test(normalized)) {
    errors.push('Password must contain an uppercase letter');
  }
  if (policy.requireLowercase && !/[a-z]/.test(normalized)) {
    errors.push('Password must contain a lowercase letter');
  }
  if (policy.requireDigit && !/[0-9]/.test(normalized)) {
    errors.push('Password must contain a digit');
  }
  if (policy.requireSymbol && !/[^A-Za-z0-9]/.test(normalized)) {
    errors.push('Password must contain a symbol');
  }

  const lower = normalized.toLowerCase();
  for (const bad of policy.blocklist) {
    if (bad && lower.includes(bad.toLowerCase())) {
      errors.push('Password contains a commonly used or forbidden phrase');
      break;
    }
  }

  if (policy.rejectUserInfo) {
    for (const info of userInfo) {
      if (!info) continue;
      const localPart = info.split('@')[0].toLowerCase();
      if (localPart.length >= 3 && lower.includes(localPart)) {
        errors.push('Password must not contain your username or email');
        break;
      }
    }
  }

  // Reject trivially repetitive or sequential passwords.
  if (/^(.)\1+$/.test(normalized)) {
    errors.push('Password must not be a single repeated character');
  }
  if (hasLongSequentialRun(lower, 5)) {
    errors.push('Password must not contain long sequential character runs');
  }

  return { valid: errors.length === 0, errors, score: estimateStrength(normalized) };
}

function hasLongSequentialRun(s: string, minRun: number): boolean {
  let asc = 1;
  let desc = 1;
  for (let i = 1; i < s.length; i++) {
    const diff = s.charCodeAt(i) - s.charCodeAt(i - 1);
    asc = diff === 1 ? asc + 1 : 1;
    desc = diff === -1 ? desc + 1 : 1;
    if (asc >= minRun || desc >= minRun) return true;
  }
  return false;
}

function estimateStrength(password: string): number {
  let pool = 0;
  if (/[a-z]/.test(password)) pool += 26;
  if (/[A-Z]/.test(password)) pool += 26;
  if (/[0-9]/.test(password)) pool += 10;
  if (/[^A-Za-z0-9]/.test(password)) pool += 33;
  const unique = new Set(password).size;
  const effectiveLength = Math.min(password.length, unique + password.length / 2);
  const entropy = pool > 0 ? effectiveLength * (Math.log2(pool) || 0) : 0;
  if (entropy < 28) return 0;
  if (entropy < 40) return 1;
  if (entropy < 60) return 2;
  if (entropy < 80) return 3;
  return 4;
}

export interface ScryptParams {
  N: number; // CPU/memory cost, power of two
  r: number; // block size
  p: number; // parallelization
  keyLength: number;
  saltLength: number;
  maxmem: number;
}

export const DEFAULT_SCRYPT_PARAMS: ScryptParams = {
  N: 1 << 15, // 32768
  r: 8,
  p: 1,
  keyLength: 32,
  saltLength: 16,
  maxmem: 128 * 1024 * 1024,
};

